49	    BinaryStream* stream, int64_t offset, int64_t totalLength)
50	    : stream_(stream), offset_(offset), totalLength_(totalLength)
51	{
52	}
53	
54	AdaptiveFileAllocationIterator::~AdaptiveFileAllocationIterator() = default;
55	
56	void AdaptiveFileAllocationIterator::allocateChunk()
57	{
58	  if (!allocator_) {
59	#ifdef HAVE_FALLOCATE
60	    try {
61	      A2_LOG_DEBUG("Testing file system supports fallocate.");
62	      if (offset_ < totalLength_) {
63	        int64_t len =
64	            std::min(totalLength_ - offset_, static_cast<int64_t>(4_k));
65	        stream_->allocate(offset_, len, false);
66	        offset_ += len;
67	      }
68	      A2_LOG_DEBUG("File system supports fallocate.");
69	      allocator_ = make_unique<FallocFileAllocationIterator>(stream_, offset_,
70	                                                             totalLength_);
71	    }
72	    catch (RecoverableException& e) {
73	      A2_LOG_DEBUG("File system does not support fallocate.");
74	      auto salloc = make_unique<SingleFileAllocationIterator>(stream_, offset_,
75	                                                              totalLength_);
76	      salloc->init();
77	      allocator_ = std::move(salloc);
78	    }
79	#else  // !HAVE_FALLOCATE
80	    auto salloc = make_unique<SingleFileAllocationIterator>(stream_, offset_,
81	                                                            totalLength_);
82	    salloc->init();
83	    allocator_ = std::move(salloc);
84	#endif // !HAVE_FALLOCATE
85	    allocator_->allocateChunk();
86	  }
87	  else {
88	    allocator_->allocateChunk();
89	  }
90	}
91	
92	bool AdaptiveFileAllocationIterator::finished()
93	{
94	  if (!allocator_) {
95	    return offset_ == totalLength_;
96	  }
97	  else {
98	    return allocator_->finished();
99	  }
100	}
